const assert = require('assert');

// Test the binary search function
const sortedArr = [1, 3, 5, 7, 9, 11, 13, 15];
assert.strictEqual(binarySearch(sortedArr, 7), 3, 'Should find element at correct index');
assert.strictEqual(binarySearch(sortedArr, 1), 0, 'Should find first element');
assert.strictEqual(binarySearch(sortedArr, 15), 7, 'Should find last element');
assert.strictEqual(binarySearch(sortedArr, 6), -1, 'Should return -1 for missing element');
assert.strictEqual(binarySearch([], 5), -1, 'Should handle empty array');
assert.strictEqual(binarySearch([1], 1), 0, 'Should handle single element array - found');
assert.strictEqual(binarySearch([1], 2), -1, 'Should handle single element array - not found');
console.log('All binary search tests passed!');

const assert = require('assert');

// Test the linked list implementation
const list = new LinkedList();
assert.strictEqual(list.display(), '', 'Empty list should display nothing');

list.addAtBeginning(1);
list.addAtBeginning(2);
list.addAtEnd(3);
list.addAtEnd(4);
assert.strictEqual(list.display(), '2 -> 1 -> 3 -> 4', 'Should display correct order after additions');

list.removeByValue(1);
assert.strictEqual(list.display(), '2 -> 3 -> 4', 'Should remove element correctly');

list.removeByValue(2);
assert.strictEqual(list.display(), '3 -> 4', 'Should remove head element correctly');

list.removeByValue(4);
assert.strictEqual(list.display(), '3', 'Should remove tail element correctly');

list.removeByValue(3);
assert.strictEqual(list.display(), '', 'Should handle removing last element');

list.removeByValue(999);
assert.strictEqual(list.display(), '', 'Should handle removing non-existent element');

console.log('All linked list tests passed!');

const assert = require('assert');

// Mock fetch function for testing
global.fetch = async (url) => {
  if (url.includes('error')) {
    throw new Error('Network error');
  }
  return {
    ok: url.includes('success'),
    json: async () => ({ data: `data from ${url}`, value: Math.floor(Math.random() * 100) })
  };
};

// Test the async data processor
(async () => {
  const urls = [
    'http://api.success1.com/data',
    'http://api.success2.com/data',
    'http://api.error.com/data',
    'http://api.invalid.com/data'
  ];

  const result = await processDataConcurrently(urls);

  assert(result.hasOwnProperty('successful'), 'Result should have successful property');
  assert(result.hasOwnProperty('failed'), 'Result should have failed property');
  assert(result.hasOwnProperty('total'), 'Result should have total property');
  assert(result.successful >= 1, 'Should have at least 1 successful result');
  assert(result.failed >= 1, 'Should have at least 1 failed result');
  assert(result.total === urls.length, 'Total should equal input length');

  console.log('All async data processor tests passed!');
})();

const assert = require('assert');

// Test the memoized Fibonacci function
const startTime = Date.now();
const result1 = fibonacciMemo(40);
const firstCallTime = Date.now() - startTime;

const startTime2 = Date.now();
const result2 = fibonacciMemo(40);
const secondCallTime = Date.now() - startTime2;

assert.strictEqual(result1, 102334155, 'Should calculate correct Fibonacci number');
assert.strictEqual(result2, 102334155, 'Should return same result on second call');
assert(secondCallTime < firstCallTime / 10, 'Second call should be significantly faster due to memoization');

// Test edge cases
assert.strictEqual(fibonacciMemo(0), 0, 'Should handle F(0) = 0');
assert.strictEqual(fibonacciMemo(1), 1, 'Should handle F(1) = 1');
assert.strictEqual(fibonacciMemo(2), 1, 'Should handle F(2) = 1');
assert.strictEqual(fibonacciMemo(10), 55, 'Should calculate F(10) correctly');

console.log('All memoized Fibonacci tests passed!');

const assert = require('assert');

// Test the EventEmitter implementation
const emitter = new EventEmitter();
let callCount = 0;
let receivedData = null;

const listener = (data) => {
  callCount++;
  receivedData = data;
};

// Test basic subscription and emission
emitter.on('test', listener);
emitter.emit('test', 'hello');
assert.strictEqual(callCount, 1, 'Listener should be called once');
assert.strictEqual(receivedData, 'hello', 'Should receive correct data');

// Test multiple emissions
emitter.emit('test', 'world');
assert.strictEqual(callCount, 2, 'Listener should be called again');
assert.strictEqual(receivedData, 'world', 'Should receive updated data');

// Test unsubscription
emitter.off('test', listener);
emitter.emit('test', 'ignored');
assert.strictEqual(callCount, 2, 'Listener should not be called after unsubscription');

// Test once listener
let onceCallCount = 0;
const onceListener = () => { onceCallCount++; };
emitter.once('once-test', onceListener);
emitter.emit('once-test');
emitter.emit('once-test');
assert.strictEqual(onceCallCount, 1, 'Once listener should only be called once');

console.log('All EventEmitter tests passed!');
